def full_rule(din, mk, K=8):
    h,w=len(din),len(din[0])
    pts=[(r,c) for r in range(h) for c in range(w) if din[r][c]==mk]
    R0=min(p[0] for p in pts); R1=max(p[0] for p in pts)
    C0=min(p[1] for p in pts); C1=max(p[1] for p in pts)
    out=[row[:] for row in din]
    # (a) pair fills with distance <= K
    for r in range(h):
        ms=sorted(c for c in range(w) if din[r][c]==mk)
        for a,b in zip(ms,ms[1:]):
            if b-a<=K+1:
                for c in range(a+1,b):
                    if out[r][c]!=mk: out[r][c]=2
    for c in range(w):
        ms=sorted(r for r in range(h) if din[r][c]==mk)
        for a,b in zip(ms,ms[1:]):
            if b-a<=K+1:
                for r in range(a+1,b):
                    if out[r][c]!=mk: out[r][c]=2
    # (b) corner arms: for each bbox corner not a marker, fill bg cells from corner along both frame lines to first marker
    corners=[(R0,C0),(R0,C1),(R1,C0),(R1,C1)]
    for (cr,cc) in corners:
        if din[cr][cc]==mk: continue
        # col arm: from corner towards first marker in that col
        colms=sorted(r for r in range(h) if din[r][cc]==mk)
        if colms:
            m=min(colms) if cr==R1 else max(colms)  # marker on this col line
