            r=cr
            while True:
                if out[r][cc]!=mk: out[r][cc]=2
                if r==m: break
                r+=step
        rowms=sorted(c for c in range(w) if din[cr][c]==mk)
        if rowms:
            m=min(rowms) if cc==C1 else max(rowms)
            step = 1 if m>cc else -1
            c=cc
            while True:
                if out[cr][c]!=mk: out[cr][c]=2
                if c==m: break
                c+=step
    return out

