def rects_rule(din, mk, thr):
    h,w=len(din),len(din[0])
    pts=[(r,c) for r in range(h) for c in range(w) if din[r][c]==mk]
    fill=set()
    for r1,c1 in pts:
        for r2,c2 in pts:
            if r2<=r1 or c2<=c1: continue
            if din[r1][c2]!=mk or din[r2][c1]!=mk: continue
            outline=[(r1,c) for c in range(c1,c2+1)]+[(r2,c) for c in range(c1,c2+1)]+[(r,c1) for r in range(r1,r2+1)]+[(r,c2) for r in range(r1,r2+1)]
            outline=set(outline)
            mkc=sum(1 for p in outline if din[p[0]][p[1]]==mk)
            if mkc/len(outline)>=thr:
                fill |= {p for p in outline if din[p[0]][p[1]]!=mk}
    out=[row[:] for row in din]
    for r,c in fill: out[r][c]=2
    return out

