def ruleI(din, mk):
    h,w=len(din),len(din[0])
    pts=[(r,c) for r in range(h) for c in range(w) if din[r][c]==mk]
    R0=min(p[0] for p in pts); R1=max(p[0] for p in pts)
    C0=min(p[1] for p in pts); C1=max(p[1] for p in pts)
    out=[row[:] for row in din]
    for r in range(h):
        for c in range(w):
            if out[r][c]!=mk and ((r in (R0,R1) and C0<=c<=C1) or (c in (C0,C1) and R0<=r<=R1)):
                out[r][c]=2
    def runlen(seq,i):  # length of run containing index i in list of marker positions
        a=i
        while a-1 in seq: a-=1
        b=i
        while b+1 in seq: b+=1
        return b-a+1
    for r in range(h):
        ms={c for c in range(w) if din[r][c]==mk}
        if r in (R0,R1): continue
        for c in range(1,w-1):
            if din[r][c]!=mk and c-1 in ms and c+1 in ms and runlen(ms,c-1)>=2 and runlen(ms,c+1)>=2:
                out[r][c]=2
    for c in range(w):
        ms={r for r in range(h) if din[r][c]==mk}
        if c in (C0,C1): continue
        for r in range(1,h-1):
            if din[r][c]!=mk and r-1 in ms and r+1 in ms and runlen(ms,r-1)>=2 and runlen(ms,r+1)>=2:
                out[r][c]=2
    return out

