def ruleJ(din, mk, thr=4):
    h,w=len(din),len(din[0])
    pts=[(r,c) for r in range(h) for c in range(w) if din[r][c]==mk]
    R0=min(p[0] for p in pts); R1=max(p[0] for p in pts)
    C0=min(p[1] for p in pts); C1=max(p[1] for p in pts)
    out=[row[:] for row in din]
    # bbox border: fill all bg on frame lines within bbox
    for r in (R0,R1):
        for c in range(C0,C1+1):
            if out[r][c]!=mk: out[r][c]=2
    for c in (C0,C1):
        for r in range(R0,R1+1):
            if out[r][c]!=mk: out[r][c]=2
    # dense interior lines: fill ALL bg gaps between consecutive markers
    for r in range(h):
        if r in (R0,R1): continue
        ms=[c for c in range(w) if din[r][c]==mk]
        if len(ms)>=thr:
            for a_,b_ in zip(ms,ms[1:]):
                for c in range(a_+1,b_):
                    out[r][c]=2
    for c in range(w):
        if c in (C0,C1): continue
        ms=[r for r in range(h) if din[r][c]==mk]
        if len(ms)>=thr:
            for a_,b_ in zip(ms,ms[1:]):
                for r in range(a_+1,b_):
                    out[r][c]=2
    return out

